const LSP={version:'8.0.0',tools:TOOLS,history:[],data:[],project:{name:'Untitled Project',events:[]}};
const $=s=>document.querySelector(s); const $$=s=>[...document.querySelectorAll(s)];
function esc(x){return String(x??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function num(x){const v=Number(x); return Number.isFinite(v)?v:NaN}
function fmt(x,n=8){if(!Number.isFinite(x))return '—'; return Number(x.toPrecision(n)).toString()}
function log(msg,meta={}){LSP.history.push({time:new Date().toISOString(),msg,meta});LSP.project.events.push(LSP.history.at(-1));renderHistory();}
const units={
 'm':1,'cm':.01,'mm':.001,'um':1e-6,'nm':1e-9,'km':1e3,'in':.0254,'ft':.3048,
 's':1,'min':60,'h':3600,'day':86400,'Hz':1,'kHz':1e3,'MHz':1e6,
 'g':1e-3,'kg':1,'mg':1e-6,'ug':1e-9,'ng':1e-12,'mol':1,'mmol':1e-3,'umol':1e-6,'nmol':1e-9,
 'L':1,'mL':1e-3,'uL':1e-6,'K':1,'Pa':1,'kPa':1e3,'MPa':1e6,'bar':1e5,'atm':101325,
 'J':1,'kJ':1e3,'cal':4.184,'kcal':4184,'W':1,'V':1,'A':1,'C':1,'Ohm':1,'F':1,'N':1,'kN':1e3
};
function convert(v,a,b){if(!(a in units)||!(b in units))throw Error('Unknown unit');return v*units[a]/units[b]}
function sigfig(x,n){if(!Number.isFinite(x)||x===0)return x; const p=n-1-Math.floor(Math.log10(Math.abs(x)));return Math.round(x*10**p)/10**p}
function mean(a){return a.reduce((s,x)=>s+x,0)/a.length} function variance(a){let m=mean(a);return a.reduce((s,x)=>s+(x-m)**2,0)/(a.length-1)} function sd(a){return Math.sqrt(variance(a))}
function median(a){a=[...a].sort((x,y)=>x-y);let n=a.length;return n%2?a[(n-1)/2]:(a[n/2-1]+a[n/2])/2}
function quantile(a,q){a=[...a].sort((x,y)=>x-y);if(!a.length)return NaN;let p=(a.length-1)*q,i=Math.floor(p),f=p-i;return a[i]+(a[i+1]??a[i]-a[i])*f}
function linreg(x,y){let n=x.length,mx=mean(x),my=mean(y),sxx=x.reduce((s,v)=>s+(v-mx)**2,0),sxy=x.reduce((s,v,i)=>s+(v-mx)*(y[i]-my),0);let slope=sxy/sxx,inter=my-slope*mx,p=y.map((v,i)=>slope*x[i]+inter),res=y.map((v,i)=>v-p[i]),sst=y.reduce((s,v)=>s+(v-my)**2,0),sse=res.reduce((s,v)=>s+v*v,0);return{n,slope,intercept,r2:1-sse/sst,r:Math.sign(slope)*Math.sqrt(Math.max(0,1-sse/sst)),RMSE:Math.sqrt(sse/n),MAE:res.reduce((s,v)=>s+Math.abs(v),0)/n,pred:p,res};}
function polyfit(x,y,d=2){let N=d+1,A=Array.from({length:N},()=>Array(N).fill(0)),b=Array(N).fill(0);for(let k=0;k<x.length;k++){let xp=1;for(let i=0;i<N;i++){let xq=xp,yv=y[k];for(let j=0;j<N;j++){A[i][j]+=xq; xq*=x[k]} b[i]+=yv*xp;xp*=x[k]}}return solve(A,b)}
function solve(A,b){A=A.map((r,i)=>[...r,b[i]]);let n=A.length;for(let i=0;i<n;i++){let p=i;for(let k=i+1;k<n;k++)if(Math.abs(A[k][i])>Math.abs(A[p][i]))p=k;[A[i],A[p]]=[A[p],A[i]];let z=A[i][i];if(Math.abs(z)<1e-15)throw Error('Singular matrix');for(let j=i;j<=n;j++)A[i][j]/=z;for(let k=0;k<n;k++){if(k===i)continue;z=A[k][i];for(let j=i;j<=n;j++)A[k][j]-=z*A[i][j]}}return A.map(r=>r[n])}
function trapz(x,y){let s=0;for(let i=1;i<x.length;i++)s+=(x[i]-x[i-1])*(y[i]+y[i-1])/2;return s}
function bisect(f,a,b,tol=1e-10,max=200){let fa=f(a),fb=f(b);if(fa*fb>0)throw Error('Root not bracketed');for(let i=0;i<max;i++){let c=(a+b)/2,fc=f(c);if(Math.abs(fc)<tol||Math.abs(b-a)<tol)return c;if(fa*fc<=0){b=c;fb=fc}else{a=c;fa=fc}}return(a+b)/2}
function normalCDF(z){return .5*(1+erf(z/Math.sqrt(2)))} function erf(x){let s=Math.sign(x),a=Math.abs(x),t=1/(1+.3275911*a);let p=((((1.061405429*t-1.453152027)*t+1.421413741)*t-.284496736)*t+.254829592);return s*(1-p*Math.exp(-a*a))}
function bootstrap(a,stat=B=>mean(B),B=2000){let out=[];for(let i=0;i<B;i++){let b=Array.from({length:a.length},()=>a[Math.floor(Math.random()*a.length)]);out.push(stat(b))}return{estimate:stat(a),lo:quantile(out,.025),hi:quantile(out,.975)}}
function shannon(counts){let s=counts.reduce((a,b)=>a+b,0);return -counts.filter(x=>x>0).reduce((h,x)=>{let p=x/s;return h+p*Math.log(p)},0)}
function simpson(counts){let s=counts.reduce((a,b)=>a+b,0);return 1-counts.reduce((z,x)=>{let p=x/s;return z+p*p},0)}
function gc(seq){seq=seq.toUpperCase().replace(/[^ACGTU]/g,'');return seq?100*(seq.match(/[GC]/g)||[]).length/seq.length:NaN}
function revcomp(s){return s.toUpperCase().replace(/[ACGT]/g,c=>({A:'T',T:'A',C:'G',G:'C'}[c])).split('').reverse().join('')}
const codon={TTT:'F',TTC:'F',TTA:'L',TTG:'L',TCT:'S',TCC:'S',TCA:'S',TCG:'S',TAT:'Y',TAC:'Y',TAA:'*',TAG:'*',TGT:'C',TGC:'C',TGA:'*',TGG:'W',CTT:'L',CTC:'L',CTA:'L',CTG:'L',CCT:'P',CCC:'P',CCA:'P',CCG:'P',CAT:'H',CAC:'H',CAA:'Q',CAG:'Q',CGT:'R',CGC:'R',CGA:'R',CGG:'R',ATT:'I',ATC:'I',ATA:'I',ATG:'M',ACT:'T',ACC:'T',ACA:'T',ACG:'T',AAT:'N',AAC:'N',AAA:'K',AAG:'K',AGT:'S',AGC:'S',AGA:'R',AGG:'R',GTT:'V',GTC:'V',GTA:'V',GTG:'V',GCT:'A',GCC:'A',GCA:'A',GCG:'A',GAT:'D',GAC:'D',GAA:'E',GAG:'E',GGT:'G',GGC:'G',GGA:'G',GGG:'G'};
function translate(s){s=s.toUpperCase().replace(/[^ACGT]/g,'');let o='';for(let i=0;i+2<s.length;i+=3)o+=codon[s.slice(i,i+3)]||'X';return o}
function mwFormula(f){let atoms={H:1.008,C:12.011,N:14.007,O:15.999,P:30.974,S:32.06,Na:22.990,K:39.098,Cl:35.45,Mg:24.305,Ca:40.078,Fe:55.845};let total=0,ok=true;for(let m of f.matchAll(/([A-Z][a-z]?)(\d*)/g)){if(!(m[1] in atoms)){ok=false;continue}total+=atoms[m[1]]*(m[2]?+m[2]:1)}return{mass:total,valid:ok}}
function pcrTm(seq){let s=seq.toUpperCase().replace(/[^ACGT]/g,'');let gcN=(s.match(/[GC]/g)||[]).length,at=s.length-gcN;return s.length<14?2*at+4*gcN:64.9+41*(gcN-16.4)/s.length}
function michaelis(S,Vmax,Km){return Vmax*S/(Km+S)}
function hill(S,Vmax,Kd,n){return Vmax*S**n/(Kd**n+S**n)}
function arrhenius(A,Ea,T){return A*Math.exp(-Ea/(8.314462618*T))}
function beer(A,e,l){return A/(e*l)}
function shannonEven(counts){let s=counts.reduce((a,b)=>a+b,0),S=counts.filter(Boolean).length;return S?shannon(counts)/Math.log(S):NaN}
function ndvi(nir,red){return (nir-red)/(nir+red)}
function lod(sdBlank,slope){return 3.3*sdBlank/Math.abs(slope)} function loq(sdBlank,slope){return 10*sdBlank/Math.abs(slope)}
function deltaCt(ctTarget,ctRef){return ctTarget-ctRef} function deltaDeltaCt(dctSample,dctControl){return dctSample-dctControl} function fold(ddct){return 2**(-ddct)}
function circularity(area,perim){return 4*Math.PI*area/(perim**2)} function feret(w,h){return Math.hypot(w,h)}
function scherrer(K,lambda,beta,theta){return K*lambda/(beta*Math.cos(theta))}
function bragg(n,lambda,theta){return n*lambda/(2*Math.sin(theta))}
function kepler(a,mu=1){return 2*Math.PI*Math.sqrt(a**3/mu)} function escapeVelocity(G,M,r){return Math.sqrt(2*G*M/r)}
function einstein(m,c=299792458){return m*c*c}
function zscore(x,m,s){return (x-m)/s} function minmax(x,min,max){return (x-min)/(max-min)} function cosine(a,b){let d=a.reduce((s,x,i)=>s+x*b[i],0),na=Math.hypot(...a),nb=Math.hypot(...b);return d/(na*nb)}
function confusion(tp,tn,fp,fn){let acc=(tp+tn)/(tp+tn+fp+fn),pre=tp/(tp+fp),rec=tp/(tp+fn),f1=2*pre*rec/(pre+rec);return{accuracy:acc,precision:pre,recall:rec,F1:f1,specificity:tn/(tn+fp)}}
function plotSVG(x,y,w=720,h=360){let px=40,py=20,pw=w-60,ph=h-50,x0=Math.min(...x),x1=Math.max(...x),y0=Math.min(...y),y1=Math.max(...y);if(x1===x0)x1=x0+1;if(y1===y0)y1=y0+1;let pts=x.map((v,i)=>`${px+(v-x0)/(x1-x0)*pw},${h-py-(y[i]-y0)/(y1-y0)*ph}`).join(' ');return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img"><rect width="100%" height="100%" fill="white"/><line x1="${px}" y1="${h-py}" x2="${w-px}" y2="${h-py}" stroke="#555"/><line x1="${px}" y1="${py}" x2="${px}" y2="${h-py}" stroke="#555"/><polyline fill="none" stroke="#0a8" stroke-width="2" points="${pts}"/>${x.map((v,i)=>`<circle cx="${px+(v-x0)/(x1-x0)*pw}" cy="${h-py-(y[i]-y0)/ (y1-y0)*ph}" r="3" fill="#1677ff"/>`).join('')}</svg>`}
const OPS={
'Scientific Calculator':{fields:['expression'],run:v=>({result:Function('return ('+v.expression+')')()})},
'Unit Conversion':{fields:['value','from','to'],run:v=>({result:convert(+v.value,v.from,v.to),unit:v.to})},
'Descriptive Statistics':{fields:['values'],run:v=>{let a=parseList(v.values);return{n:a.length,mean:mean(a),median:median(a),sd:sd(a),variance:variance(a),min:Math.min(...a),max:Math.max(...a),q1:quantile(a,.25),q3:quantile(a,.75)}}},
'Linear Regression':{fields:['x','y'],run:v=>linreg(parseList(v.x),parseList(v.y))},
'Polynomial Regression':{fields:['x','y','degree'],run:v=>({coefficients:polyfit(parseList(v.x),parseList(v.y),+v.degree||2)})},
'Numerical Integration':{fields:['x','y'],run:v=>({area:trapz(parseList(v.x),parseList(v.y))})},
'Root Finding':{fields:['expression','a','b'],run:v=>({root:bisect(x=>Function('x','return '+v.expression)(x),+v.a,+v.b)})},
'Bootstrap':{fields:['values','iterations'],run:v=>bootstrap(parseList(v.values),B=>mean(B),+v.iterations||2000)},
'Shannon Diversity':{fields:['counts'],run:v=>({H:shannon(parseList(v.counts)),evenness:shannonEven(parseList(v.counts))})},
'Simpson Index':{fields:['counts'],run:v=>({index:simpson(parseList(v.counts))})},
'GC Content':{fields:['sequence'],run:v=>({GC_percent:gc(v.sequence),length:v.sequence.replace(/[^ACGTU]/gi,'').length})},
'Reverse Complement':{fields:['sequence'],run:v=>({sequence:revcomp(v.sequence)})},
'DNA Translation':{fields:['sequence'],run:v=>({protein:translate(v.sequence)})},
'Primer Tm':{fields:['sequence'],run:v=>({Tm_C:pcrTm(v.sequence)})},
'Molar Mass':{fields:['formula'],run:v=>mwFormula(v.formula)},
'Michaelis-Menten':{fields:['S','Vmax','Km'],run:v=>({v:michaelis(+v.S,+v.Vmax,+v.Km)})},
'Hill Equation':{fields:['S','Vmax','Kd','n'],run:v=>({v:hill(+v.S,+v.Vmax,+v.Kd,+v.n)})},
'Beer-Lambert':{fields:['absorbance','epsilon','pathlength'],run:v=>({concentration:beer(+v.absorbance,+v.epsilon,+v.pathlength)})},
'Arrhenius':{fields:['A','Ea_Jmol','T_K'],run:v=>({k:arrhenius(+v.A,+v.Ea_Jmol,+v.T_K)})},
'qPCR ΔCt':{fields:['Ct_target','Ct_reference'],run:v=>({deltaCt:deltaCt(+v.Ct_target,+v.Ct_reference)})},
'qPCR ΔΔCt':{fields:['ΔCt_sample','ΔCt_control'],run:v=>{let d=deltaDeltaCt(+v['ΔCt_sample'],+v['ΔCt_control']);return{ΔΔCt:d,foldChange:fold(d)}}},
'LOD':{fields:['blankSD','slope'],run:v=>({LOD:lod(+v.blankSD,+v.slope)})},
'LOQ':{fields:['blankSD','slope'],run:v=>({LOQ:loq(+v.blankSD,+v.slope)})},
'NDVI':{fields:['NIR','Red'],run:v=>({NDVI:ndvi(+v.NIR,+v.Red)})},
'Circularity':{fields:['area','perimeter'],run:v=>({circularity:circularity(+v.area,+v.perimeter)})},
'Feret Diameter':{fields:['width','height'],run:v=>({Feret:feret(+v.width,+v.height)})},
'Scherrer Crystallite Size':{fields:['K','lambda_nm','beta_rad','theta_rad'],run:v=>({size_nm:scherrer(+v.K,+v.lambda_nm*1e-9,+v.beta_rad,+v.theta_rad)*1e9})},
'XRD Bragg Law':{fields:['n','lambda','theta_rad'],run:v=>({d:bragg(+v.n,+v.lambda,+v.theta_rad)})},
'Kepler Law':{fields:['semiMajorAxis','mu'],run:v=>({period:kepler(+v.semiMajorAxis,+v.mu)})},
'Photon Energy':{fields:['wavelength_m'],run:v=>({E_J:6.62607015e-34*299792458/+v.wavelength_m})},
'Radioactive Decay':{fields:['N0','lambda','t'],run:v=>({N:+v.N0*Math.exp(-+v.lambda*+v.t)})},
'Einstein Mass-Energy':{fields:['mass_kg'],run:v=>({energy_J:einstein(+v.mass_kg)})},
'Confusion Matrix':{fields:['TP','TN','FP','FN'],run:v=>confusion(+v.TP,+v.TN,+v.FP,+v.FN)},
'Z-score':{fields:['x','mean','sd'],run:v=>({z:zscore(+v.x,+v.mean,+v.sd)})},
'Min-Max Scaling':{fields:['x','min','max'],run:v=>({scaled:minmax(+v.x,+v.min,+v.max)})},
'Cosine Similarity':{fields:['a','b'],run:v=>({cosine:cosine(parseList(v.a),parseList(v.b))})},
'Power':{fields:['voltage','current'],run:v=>({power_W:+v.voltage*+v.current})},
'Ohm Law':{fields:['voltage','resistance'],run:v=>({current_A:+v.voltage/+v.resistance})},
'Stress':{fields:['force','area'],run:v=>({stress:+v.force/+v.area})},
'Young Modulus':{fields:['stress','strain'],run:v=>({E:+v.stress/+v.strain})},
};
// Scientific integrity: a module is labelled implemented only when an executable local engine or recovered calculator exists.
(function normalizeModuleStatus(){ const catalog=(typeof CALCULATORS!=='undefined'?CALCULATORS:[]); const names=new Set(catalog.map(x=>x.name)); TOOLS.forEach(t=>{ if(t.status==='implemented' && !OPS[t.name] && !names.has(t.name)) t.status='framework'; }); })();
function parseList(s){return String(s).split(/[ ,;\n\t]+/).map(Number).filter(Number.isFinite)}
const FALLBACK_FIELDS=['value'];
function catalogTool(name){
 const c=(typeof CALCULATORS!=='undefined'?CALCULATORS:[]).find(x=>x.name===name);
 if(!c)return null;
 return {fields:(c.fields||[]).map(f=>f.key),meta:c,run:v=>{
   const keys=(c.fields||[]).map(f=>f.key); const args=keys.map(k=>Number(v[k]));
   if(args.some(x=>!Number.isFinite(x))) throw new Error('All numeric inputs must be finite numbers.');
   const fn=new Function(...keys,'Math',`"use strict";return (${c.expr});`);
   const result=fn(...args,Math); return {value:result,formula:c.formula,units:(c.fields||[]).map(f=>f.unit),description:c.description};
 }};
}
function openTool(name){let t=OPS[name]||catalogTool(name)||{fields:FALLBACK_FIELDS,run:v=>({status:'framework',message:'This module is registered as a framework/reference module; no unsupported result is fabricated.'})};let meta=t.meta||{};$('#workspace').innerHTML=`<div class="toolhead"><div><span class="badge">${esc(toolByName(name)?.domain||'Module')}</span><h2>${esc(name)}</h2><p>${esc(meta.formula||'Enter inputs and run the validated local calculation, or use this as a method/reference module.')}</p>${meta.description?`<p>${esc(meta.description)}</p>`:''}</div></div><div class="formgrid">${t.fields.map(f=>{let ff=(meta.fields||[]).find(x=>x.key===f);return `<label>${esc(ff?.label||f)}${ff?.unit?` <small>(${esc(ff.unit)})</small>`:''}<input data-f="${esc(f)}" value="${defaults(f) || ff?.default || ''}"></label>`}).join('')}</div><div class="actions"><button id="run">Run calculation</button><button id="save">Save result</button></div><pre id="result">Ready.</pre><div id="plot"></div>`;
$('#run').onclick=()=>{try{let v=Object.fromEntries($$('#workspace [data-f]').map(i=>[i.dataset.f,i.value]));let r=t.run(v);$('#result').textContent=JSON.stringify(r,null,2);log(name,{inputs:v,result:r});if(r.pred&&v.x){let x=parseList(v.x);$('#plot').innerHTML=plotSVG(x,parseList(v.y))}}catch(e){$('#result').textContent='Error: '+e.message}};
$('#save').onclick=()=>{log('Saved result',{tool:name,result:$('#result').textContent});alert('Saved to project history.')}}
function defaults(f){return ({expression:'2+2',value:'1',from:'m',to:'cm',x:'1,2,3,4,5',y:'2,4,5,8,10',degree:'2',values:'1,2,3,4,5',iterations:'2000',sequence:'ATGCGTACCGTAGCTAGCTAA',formula:'C6H12O6',S:'1',Vmax:'1',Km:'0.5',epsilon:'10000',pathlength:'1',absorbance:'1',blankSD:'0.01',slope:'1',NIR:'0.7',Red:'0.3',area:'100',perimeter:'40',width:'10',height:'10',K:'0.9',lambda_nm:'0.154',beta_rad:'0.01',theta_rad:'0.5',n:'1',lambda:'1',theta:'0.5',semiMajorAxis:'1',mu:'1',wavelength_m:'5e-7',N0:'1000',t:'10',mass_kg:'1e-12',TP:'80',TN:'90',FP:'10',FN:'20',mean:'5',sd:'2',min:'0',max:'10',a:'1,2,3',b:'2,3,4',voltage:'5',current:'2',resistance:'10',force:'100',strain:'0.01'})[f]??''}
function toolByName(n){return TOOLS.find(x=>x.name===n)}
function renderTools(q=''){let a=TOOLS.filter(t=>(t.name+' '+t.domain).toLowerCase().includes(q.toLowerCase()));$('#toolList').innerHTML=a.map(t=>`<button class="tool ${t.status==='framework'?'framework':''}" data-tool="${esc(t.name)}"><span>${esc(t.name)}</span><small>${esc(t.domain)}</small></button>`).join('');$$('[data-tool]').forEach(b=>b.onclick=()=>openTool(b.dataset.tool));$('#count').textContent=`${a.length} modules`}
function renderHistory(){$('#history').textContent=LSP.history.map(x=>x.time+' — '+x.msg).join('\n')||'No history yet.'}
function csvParse(text){
 const lines=String(text).replace(/\r/g,'').split('\n').filter(x=>x.trim().length);
 return lines.map(line=>{let out=[],cur='',q=false;for(let i=0;i<line.length;i++){let c=line[i];if(c==='"'){if(q&&line[i+1]==='"'){cur+='"';i++;}else q=!q;}else if(c===','&&!q){out.push(cur);cur='';}else cur+=c;}out.push(cur);return out;});
}
function csvString(rows){return rows.map(r=>r.map(v=>{let x=String(v??'');return /[",\n]/.test(x)?'"'+x.replaceAll('"','""')+'"':x}).join(',')).join('\n')}
function dataLab(){
 let rows=LSP.data.length?LSP.data:[['x','y','derived'],['1','2',''],['2','4',''],['3','6','']];
 const render=()=>{
  $('#workspace').innerHTML=`<div class="toolhead"><span class="badge">Data / Excel Engine</span><h2>Scientific Data Lab</h2><p>Local spreadsheet-style workspace for raw data, derived columns, QC, statistics, formulas and reproducible exports. Original imported values should be preserved; derived values are kept separately.</p><div class="data-actions"><input id="fileIn" type="file" accept=".csv,.tsv,.txt"><button id="loadText">Load pasted CSV</button><button id="addCol">Add column</button><button id="addRow">Add row</button><button id="analyze">QC + statistics</button><button id="export">Export CSV</button><button id="projectExport">Export project JSON</button></div><textarea id="csv" rows="6" aria-label="CSV input">${esc(csvString(rows))}</textarea><div class="sheetwrap"><table id="sheet"><thead></thead><tbody></tbody></table></div><pre id="result">Ready.</pre></div>`;
  const table=$('#sheet');
  const draw=()=>{let h=rows[0]||[];table.querySelector('thead').innerHTML='<tr>'+h.map((x,j)=>`<th contenteditable="true" data-head="${j}">${esc(x)}</th>`).join('')+'</tr>';table.querySelector('tbody').innerHTML=rows.slice(1).map((r,i)=>'<tr>'+h.map((_,j)=>`<td contenteditable="true" data-r="${i}" data-c="${j}">${esc(r[j]??'')}</td>`).join('')+'</tr>').join('');$$('[contenteditable]').forEach(el=>el.oninput=()=>{if(el.dataset.head!==undefined)rows[0][+el.dataset.head]=el.textContent;else rows[+el.dataset.r+1][+el.dataset.c]=el.textContent;LSP.data=rows;});};
  draw();
  $('#loadText').onclick=()=>{rows=csvParse($('#csv').value);LSP.data=rows;draw();log('Loaded CSV',{rows:Math.max(0,rows.length-1),columns:rows[0]?.length||0});};
  $('#fileIn').onchange=e=>{let f=e.target.files?.[0];if(!f)return;f.text().then(t=>{rows=csvParse(t);LSP.data=rows;draw();log('Imported file',{name:f.name,rows:Math.max(0,rows.length-1),columns:rows[0]?.length||0})});};
  $('#addCol').onclick=()=>{let name='derived_'+((rows[0]?.length||0)+1);rows.forEach((r,i)=>r.push(i? '':' '+name));rows[0][rows[0].length-1]=name;LSP.data=rows;draw();};
  $('#addRow').onclick=()=>{rows.push(Array(rows[0]?.length||1).fill(''));LSP.data=rows;draw();};
  $('#analyze').onclick=()=>{let h=rows[0]||[],out={rows:Math.max(0,rows.length-1),columns:h.length,missing:0,duplicates:0,columns:{}};let seen=new Set();for(let i=1;i<rows.length;i++){let key=JSON.stringify(rows[i]);if(seen.has(key))out.duplicates++;seen.add(key);for(let j=0;j<h.length;j++)if(String(rows[i][j]??'').trim()==='')out.missing++;}for(let j=0;j<h.length;j++){let a=rows.slice(1).map(r=>Number(r[j])).filter(Number.isFinite);if(a.length)out.columns[h[j]]={n:a.length,mean:mean(a),sd:a.length>1?sd(a):0,min:Math.min(...a),max:Math.max(...a)};}$('#result').textContent=JSON.stringify(out,null,2);log('Data QC',{summary:out});};
  $('#export').onclick=()=>download(csvString(rows),'data.csv','text/csv');
  $('#projectExport').onclick=()=>download(JSON.stringify({schema:'LabSuiteProProject/v1',version:LSP.version,project:LSP.project,data:rows,history:LSP.history},null,2),'lab-suite-project.json','application/json');
 };
 render();
}

function download(data,name,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([data],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function bufferLab(q=''){
 const data=(typeof BUFFERS!=='undefined'?BUFFERS:[]);
 $('#workspace').innerHTML=`<div class="toolhead"><span class="badge">Laboratory Reference</span><h2>Buffer & Solution Reference</h2><p>Search the recovered buffer reference catalog. Reference entries are informational; preparation must follow the appropriate validated protocol, reagent grade, safety requirements and institutional SOP.</p><div class="methodfilters"><input id="bufferSearch" placeholder="Search buffer, type, use, pH…" value="${esc(q)}"></div></div><div id="bufferCards" class="methodcards"></div>`;
 const render=()=>{const qq=$('#bufferSearch').value.toLowerCase();const x=data.filter(b=>Object.values(b).join(' ').toLowerCase().includes(qq));$('#bufferCards').innerHTML=x.map(b=>`<article class="methodcard"><span class="badge">${esc(b.type)}</span><h3>${esc(b.name)}</h3><p><b>pH:</b> ${esc(b.pH)}</p><p><b>Use:</b> ${esc(b.use)}</p><p><b>Notes:</b> ${esc(b.notes)}</p></article>`).join('')||'<div class="toolhead">No matching buffer.</div>'};
 $('#bufferSearch').oninput=render;render();
}

function home(){ $('#workspace').innerHTML=`<div class="welcome"><span class="badge">Lab Suite Pro v8</span><h1>Universal Scientific Workstation</h1><p>Calculate → validate → visualize → document → export.</p><div class="cards"><div><b>${TOOLS.length}</b><span>registered scientific modules</span></div><div><b>${SCIENCE_METHODS.length}</b><span>methods / instrument records</span></div><div><b>Local-first</b><span>data processing by default</span></div></div><div class="integrity"><h3>Scientific integrity boundary</h3><p>Lab Suite Pro performs calculations, modelling, visualization and analysis of supplied data. It does not invent experimental measurements. XRD, Raman, FTIR, SEM, TEM, AFM, XPS, DLS, BET, TGA, DSC, NMR, HPLC, GC-MS, flow cytometry and similar measurements require the appropriate real instrument.</p><p><b>Workflow:</b> plan method → acquire measurement with the real instrument → import raw/exported data → validate metadata and units → analyse → visualize → report → preserve provenance.</p></div></div>`}

function methodsLab(q=''){
 const a=SCIENCE_METHODS.filter(m=>(m.domain+' '+m.name+' '+m.what+' '+m.why+' '+m.how).toLowerCase().includes(q.toLowerCase()));
 const groups=[...new Set(a.map(x=>x.domain))];
 $('#workspace').innerHTML=`<div class="toolhead"><span class="badge">Scientific knowledge + instrument reality</span><h2>Methods & Instruments</h2><p>Use this section to distinguish what Lab Suite Pro can calculate/analyse locally from measurements that require physical laboratory or analytical instruments. A phone may analyse exported data or images; it cannot replace an XRD, Raman spectrometer, SEM, TEM, AFM, XPS, DLS, BET, TGA, DSC, flow cytometer, plate reader or other measurement instrument.</p><div class="methodfilters"><input id="methodSearch" placeholder="Search methods, instruments, principles…" value="${esc(q)}"><select id="methodDomain"><option value="">All domains</option>${groups.map(g=>`<option>${esc(g)}</option>`).join('')}</select></div></div><div id="methodCards" class="methodcards"></div>`;
 const render=()=>{let qq=$('#methodSearch').value.toLowerCase(),d=$('#methodDomain').value;let x=SCIENCE_METHODS.filter(m=>(!d||m.domain===d)&&((m.domain+' '+m.name+' '+m.what+' '+m.why+' '+m.how).toLowerCase().includes(qq)));$('#methodCards').innerHTML=x.map(m=>`<article class="methodcard"><div class="methodtop"><span class="badge">${esc(m.domain)}</span><span class="cap ${m.phone==='full_local'?'local':m.phone==='analysis_only'?'analysis':'instrument'}">${esc(m.phone.replaceAll('_',' '))}</span></div><h3>${esc(m.name)}</h3><p><b>What:</b> ${esc(m.what)}</p><p><b>How:</b> ${esc(m.how)}</p><p><b>Why:</b> ${esc(m.why)}</p><p><b>What is needed:</b> ${esc(m.needs||'See method requirements')}</p>${m.output?`<p><b>Output:</b> ${esc(m.output)}</p>`:''}<p class="truth"><b>Reality:</b> ${m.type==='instrument_method'?'Physical measurement requires the named instrument. Lab Suite Pro can document, calculate and analyse the resulting data; it does not fabricate a measurement.':m.type==='software_after_measurement'?'The underlying measurement must come from the physical instrument. This module performs the mathematical analysis of supplied data.':'This is a computational/reference workflow and does not claim to measure a physical quantity by itself.'}</p></article>`).join('')||'<div class="toolhead">No matching method.</div>'};$('#methodSearch').oninput=render;$('#methodDomain').onchange=render;render();
}

function init(){document.body.innerHTML=`<header><div class="brand">LAB SUITE <b>PRO</b><small>Universal Scientific Workstation v8</small></div><input id="search" placeholder="Search tools, equations, domains…"><button id="bio">BioScience</button><button id="methods">Methods</button><button id="buffers">Buffers</button><button id="data">Data Lab</button><button id="home">Home</button></header><main><aside><div class="sidehead"><b>SCIENCE MODULES</b><span id="count"></span></div><div id="toolList"></div></aside><section><div id="workspace"></div><details><summary>Project history / provenance</summary><pre id="history">No history yet.</pre></details></section></main>`;$('#search').oninput=e=>renderTools(e.target.value);$('#home').onclick=home;$('#bio').onclick=()=>bioHub();$('#methods').onclick=()=>methodsLab();$('#buffers').onclick=()=>bufferLab();$('#data').onclick=dataLab;renderTools();home()}
window.addEventListener('DOMContentLoaded',init);

// Register the local service worker when supported (GitHub Pages / HTTPS or localhost).
if(typeof navigator!=='undefined' && 'serviceWorker' in navigator){ window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{})); }
